INSERT INTO games (slug, name, description, long_description, rules, difficulty, estimated_time, icon, color, play_count, is_active, has_survival) VALUES
('word-ladder', 'Word Ladder', 'Change one letter at a time to climb from the start word to the target word!', 'Transform one word into another, one letter at a time! You\'re given a start word and a target word. Each step, change exactly one letter to form a new valid word. Can you find the shortest path? Beat par for bonus points, and discover all the possible routes!', '["You\'re given a start word at the top and a target word at the bottom","Change exactly one letter at a time to form a new valid word","Each word in the ladder must be a real English word","Try to reach the target in as few steps as possible","Beat par (the optimal number of steps) for bonus points!","Use hints to reveal the next word in the optimal path (costs points)"]', 'medium', '3-5 min', 'GitBranch', 'hsl(262, 83%, 58%)', 0, true, false),
('anagram-solver', 'Anagram Solver', 'Use the given word to find all possible anagrams.', 'Challenge yourself with anagram puzzles! You\'ll be shown a word, and your task is to find all the anagram variations that can be formed from its letters. How many can you discover?', '["You are given a base word","Enter all the anagrams you can find","Each anagram uses the exact same letters","Find all anagrams to complete the round","Build streaks for bonus points"]', 'easy', '2-3 min', 'Shuffle', 'hsl(158, 64%, 40%)', 0, true, false),
('word-scramble', 'Word Scramble', 'Unscramble letters to reveal hidden words before running out of lives.', 'Test your word unscrambling skills in this fast-paced game! Each round presents you with a scrambled word and a category hint. Type the correct word to score points and advance through levels. But be careful - you only have 3 lives, so wrong answers cost you dearly!', '["Unscramble the letters to form the hidden word","Use the category hint to guide your guess","Type your answer and press Enter or click Submit","You have 3 lives - wrong answers lose a life","Complete words to level up and earn bonus points"]', 'hard', '5-10 min', 'Puzzle', 'hsl(35, 92%, 50%)', 0, true, false),
('definition-match', 'Definition Match', 'Read the definition and guess the word it describes.', 'Expand your vocabulary in this definition-based word game! You\'ll be shown a definition and must figure out which word it describes. The part of speech is provided as a hint. Score points for each correct answer and build your streak for bonus points. Perfect for vocabulary building!', '["Read the definition carefully","Type the word that matches the definition","Part of speech is shown as a hint","Case doesn\'t matter - just spell it right!","Build streaks for bonus points"]', 'medium', '3-5 min', 'BookOpen', 'hsl(210, 70%, 50%)', 0, true, false),
('letter-pool', 'Letter Pool', 'Spell out hidden words letter by letter — choose Pool mode or go Blind!', 'All letters are hidden — spell each word from left to right, one letter at a time. Choose \'With Pool\' mode to see scrambled letters as a reference (click or type), or go \'Without Pool\' for the ultimate blind challenge. Correct letters fill in with a satisfying sound, wrong ones cost a life. Request a hint to reveal the category, but it costs points!', '["Two modes: With Pool (see scrambled letters) or Without Pool (blind)","Type or click any letter that belongs in the word","Correct letters snap into their correct position automatically","Spell letters in order (left to right) for bonus points!","Wrong letters cost a life — you have 3 lives","Request a hint to see the word\'s category (costs 20% of points)"]', 'medium', '4-6 min', 'LayoutGrid', 'hsl(340, 75%, 55%)', 0, true, false),
('word-maker', 'Word Maker', 'Create as many words as you can from a given set of letters.', 'How many words can you make? You\'re given a base word, and your challenge is to form as many smaller words as possible using only its letters. Each letter can only be used once per word. Find all the target words to win!', '["Form words using letters from the base word","Each letter can only be used once per word","Words must be at least 3 letters long","Find the target number of words to win","Duplicate words don\'t count"]', 'hard', '5-8 min', 'Sparkles', 'hsl(280, 65%, 55%)', 0, true, false),
('word-length', 'Length Challenge', 'Form words of specific lengths with different constraint variations.', 'Challenge yourself with word length puzzles! Choose from 5 different variations, each with unique constraints. Form 20 valid words matching your chosen variation\'s requirements before time runs out!', '["Choose from 5 different challenge variations","Variation 1: Form words of a specific length","Variation 2: Same length + must start with a specific letter","Variation 3: Same length + must end with a specific letter","Variation 4: Same length + starts with letter + contains letter","Variation 5: Same length + ends with letter + contains letter","Complete 20 words per variation"]', 'hard', '8-12 min', 'Ruler', 'hsl(190, 70%, 45%)', 0, true, true),
('letter-position', 'Position Master', 'Find words with the right letter at the right position!', 'Put your word knowledge to the ultimate test! You\'ll be given a position number and a letter - form words where that letter appears exactly at that position. Choose from 2 challenge variations to test your skills!', '["Form words with the given letter at the specified position","Challenge 1: Same constraint for all 20 words","Challenge 2: Constraint changes after each correct word","Words must be valid English words","Beat the clock to complete the challenge"]', 'hard', '6-10 min', 'MapPin', 'hsl(45, 85%, 50%)', 0, true, true),
('letter-hunt', 'Letter Hunt', 'Find words with exact letter counts - match the pattern!', 'Think you know your words? You\'ll be given a set of required letters, and your challenge is to find words that contain exactly those letters - no more, no less! Choose from 6 challenge variations with 2-6 required letters, or try Advanced mode where the letters change after each correct word.', '["Find words containing the required letters","Words must have EXACTLY the right count of each letter","Example: If \'A\' appears once, your word must have exactly 1 \'A\'","Challenges 1-5: Fixed letter count (2-6 letters)","Advanced: Random letter count, changes after each correct word","Words must be valid English words"]', 'medium', '6-10 min', 'Search', 'hsl(320, 70%, 50%)', 0, true, true),
('word-chain', 'Word Chain', 'Create words using the ending letters of the previous word in a back-and-forth chain.', 'Engage in a word chain battle! We give you a word, and you must form a new word starting with its last letter (or last two letters in advanced modes). The chain goes back and forth - we respond with our word, and you counter. Complete 100 words per level to advance! Quick thinking required as the timer runs for each word.', '["Variation 1, Level 1: Your word must start with the last letter of our word","Variation 1, Level 2: Same as above, plus your word must match our word\'s length","Variation 2, Level 1: Your word must start with the last TWO letters of our word","Variation 2, Level 2: Same as above, plus your word must match our word\'s length","Complete 100 valid words per level to advance","Beat the timer for each word or lose!"]', 'hard', '10-15 min', 'Link', 'hsl(170, 65%, 45%)', 0, true, true),
('letter-balance', 'Letter Balance', 'Form words based on vowel and consonant requirements across many variations.', 'Master the art of balancing vowels and consonants! Choose your challenge from multiple variations - form words with specific numbers of vowels or consonants, or words that start/end with certain letter types. Each variation offers a unique puzzle!', '["Choose from 5 different challenge variations","Consonant Count: Words with exactly 2, 3, or 4 consonants","Vowel Count: Words with exactly 2, 3, or 4 vowels","Start & End Consonant: Words beginning and ending with consonants","Start Vowel, End Consonant: Words starting with a vowel, ending with a consonant","Start Consonant, End Vowel: Words starting with a consonant, ending with a vowel","Complete 20 words per round across 5 rounds"]', 'medium', '8-12 min', 'Type', 'hsl(250, 65%, 55%)', 0, true, false),
('letter-frequency', 'Letter Frequency', 'Find words where a specific letter appears exactly N times!', 'Test your vocabulary with letter frequency challenges! You\'ll be given a letter and a count - form words where that letter appears exactly that many times. Progress through increasingly difficult challenges from 2 occurrences up to 5+!', '["Form words with the required letter appearing exactly the specified number of times","Challenge 1: Find words with exactly 2 occurrences of a letter","Challenge 2: Find words with exactly 3 occurrences","Challenge 3: Find words with exactly 4 occurrences","Challenge 4: Find words with 5+ occurrences","Challenge Random: Frequency changes after each correct word","Words must be valid English words"]', 'hard', '6-10 min', 'Hash', 'hsl(320, 70%, 50%)', 0, true, true),
('word-stack', 'Word Stack', 'Build words one letter at a time from a 2-letter base to the target word!', 'Stack your way to the target! Start with a 2-letter word and build up by adding one letter at a time. Each new word must contain all the letters from the previous word. Can you reach the top of the stack?', '["Start with a given 2-letter word","Add one letter to form a new valid word","Each word must contain all letters from the previous word","Continue until you reach the target word length","Use the hint to guide you toward the target word"]', 'hard', '5-8 min', 'Layers', 'hsl(25, 85%, 55%)', 0, true, false),
('no-repeats', 'No Repeats', 'Find words where every letter is unique - no repeating letters allowed!', 'Challenge your vocabulary with words that have no repeating letters! From 3-letter words to 9-letter masterpieces, every letter in your word must be different. Can you think of words without any duplicate letters?', '["Enter words where every letter is unique (no letter appears more than once)","Challenge 3: Find 3-letter words with all unique letters","Challenge 4: Find 4-letter words with all unique letters","Challenge 5-9: Progressively longer words with unique letters","Words must be valid English words","Score points based on word length - longer words earn more!"]', 'medium', '5-8 min', 'Fingerprint', 'hsl(180, 70%, 45%)', 0, true, true),
('word-split', 'Word Split', 'Split a word into smaller valid words that use all its letters!', 'Can you break a word apart? You\'ll be shown a target word, and your challenge is to find smaller words whose letters combine to spell the target word exactly. Each letter can only be used once across all your words. Think strategically - some splits might leave impossible leftovers!', '["You are given a target word to split","Find smaller words whose letters add up to the target word","Each letter in the target word can only be used once","Words must be at least 2 letters long","You need at least 2 words to complete a split","All letters must be covered - no leftovers allowed"]', 'hard', '5-10 min', 'Scissors', 'hsl(15, 80%, 50%)', 0, true, false),
('progressive-reveal', 'Progressive Reveal', 'Reveal letters one at a time and guess the word before you run out!', 'All the letters are hidden behind tiles. You know the category and how many letters the word has - that\'s it. Tap any tile to reveal the letter underneath, but each reveal costs you points. Can you figure out the word with the fewest reveals for the highest score? Be careful though - wrong guesses cost a life!', '["All letters start hidden behind tiles","You see the category and word length as your only clues","Tap any tile to reveal the letter underneath","Each reveal reduces your potential score for that word","Type your guess when you think you know the word","Wrong guesses cost a life - you have 3 lives","Fewer reveals = higher score"]', 'hard', '5-8 min', 'Eye', 'hsl(270, 65%, 55%)', 0, true, false),
('word-sweep', 'Word Sweep', 'Select letters from a grid to form words and clear the board!', 'A grid of letters awaits! Pick any letters from anywhere on the board to spell words. Valid words clear those letters from the grid, and remaining letters collapse downward. Use strategy to create chain reactions of new word possibilities. Can you clear the entire grid for a perfect score?', '["A 6x6 grid is filled with random letters","Click any letters from anywhere on the grid to spell a word","Words must be at least 3 letters long","Valid words clear those letters from the grid","Remaining letters collapse downward to fill gaps","Use the shuffle button (3 uses) to rearrange letters when stuck","Longer words earn exponentially more points","Clear the entire grid for a massive bonus"]', 'medium', '5-10 min', 'Grid3X3', 'hsl(200, 70%, 50%)', 0, true, false),
('word-roots', 'Word Roots', 'Find the parent word that all the given derivatives come from!', 'Can you reverse-engineer a word? You\'ll be shown 5 derivative words and your challenge is to find a parent word that contains all of them. Any valid word works — as long as all 5 derivatives can be formed from its letters. But can you find our exact word for a bonus?', '["You\'re shown 5 derivative words as clues","Find a parent word whose letters can spell all 5 derivatives","Each letter in your word can be used as many times as it appears","Any valid dictionary word that satisfies all clues is accepted","Match our intended word exactly for a bonus 50 points!","Complete 5 rounds in 3 minutes"]', 'medium', '3-5 min', 'TreePine', 'hsl(142, 60%, 40%)', 0, true, false),
('ladder-rush', 'Ladder Rush', 'Build the longest word chain you can — change one letter at a time before the clock runs out!', 'Race against the clock in this fast-paced word chain game! Starting from a given word, change exactly one letter at a time to form a new valid word. Keep the chain going as long as possible in 90 seconds. Choose your difficulty: 4-letter words for a speedy warm-up, 5-letter for a real challenge, or 6-letter words for expert mode. Every word you chain adds to your score!', '["Choose your word length: 4 letters (Easy), 5 letters (Medium), or 6 letters (Hard)","You are given a starting word","Change exactly ONE letter at a time to form a new valid word","The changed letter must be in the same position — no rearranging!","You have 90 seconds — chain as many words as possible","Each word in the chain must be a real English word","Words already used in your chain cannot be reused","Score = total number of words you chain beyond the starting word"]', 'hard', '1-2 min', 'Zap', 'hsl(38, 92%, 50%)', 0, true, true),
('ladder-rush-double', 'Ladder Rush: Double Swap', 'Change two letters at a time and chain as many words as possible before the clock runs out!', 'A faster, wider version of Ladder Rush! Starting from a given word, change exactly two letters at a time to form a new valid word. More possible neighbors means longer chains — but you still need to think quick. Choose 4, 5, or 6-letter words, and tackle Classic or Survival mode.', '["Choose your word length: 4 letters (Easy), 5 letters (Medium), or 6 letters (Hard)","You are given a starting word","Change exactly TWO letters at a time to form a new valid word","Changes are counted by letter frequency — no rearranging the same letters","You have 90 seconds — chain as many words as possible","Each word in the chain must be a real English word","Words already used in your chain cannot be reused","Score = number of words you chain beyond the starting word"]', 'medium', '1-2 min', 'Zap', 'hsl(38, 92%, 50%)', 0, true, true),
('shell-words', 'Shell Words', 'Find words that hide another word inside — remove the first and last letter to reveal it!', 'A hidden word lurks inside every shell word! Remove the first and last letter of any valid word to reveal the inner word. For example, MORALE → ORAL, BRAND → RAN, GRAPE → RAP. Play Blitz mode to find as many shell words as you can in 90 seconds, or try Wrapper mode where you\'re given an inner word and must find all the outer shells that wrap it!', '["A shell word is a word where removing the first AND last letter reveals another valid word","Example: BRAND → RAN, MORALE → ORAL, GRAPE → RAP","Blitz mode: Enter as many shell words as possible in 90 seconds","Wrapper mode: You\'re given an inner word — find all words that wrap around it","The server validates all words — the dictionary never leaves the server","Longer outer words score more points in Blitz mode"]', 'medium', '2-3 min', 'Shell', 'hsl(175, 60%, 40%)', 0, true, false),
('word-bloom', 'Word Bloom', 'Grow a short seed word into the longest chain you can — one letter at a time!', 'Start with a short seed word and grow it step by step — insert one letter anywhere (without rearranging) to form a new valid word, then keep building from there. For example: AM → AIM → AIMS → MAIMS. Every step must be exactly one letter longer than the previous. How deep can your chain go?', '["You are given a short seed word (2–4 letters)","Insert exactly one letter anywhere to form a new valid word (no rearranging)","Each step must be exactly one letter longer than the previous","Scoring: 10 pts base + 5 pts for each letter added beyond the seed length","Example: seed AM (2 letters) → AIM (3) = 10+5×1 = 15 pts; AIM → AIMS (4) = 10+5×2 = 20 pts","Classic: 2 minutes — grow the chain as deep as possible","Survival: 8 seconds per step — find any valid next word to reset the clock","The dictionary never leaves the server — all validation is server-side"]', 'hard', '2-3 min', 'Sprout', 'hsl(142, 60%, 40%)', 0, true, true),
('deep-shell-words', 'Deep Shell Words', 'Strip the first two and last two letters to reveal the hidden inner word — a deeper challenge!', 'A more devious twist on Shell Words! Remove the first TWO and last TWO letters of any valid word to reveal a hidden inner word. For example, STRANGER → RANG, SPLINTER → LINT, SPRINGER → RING. Three variations: Blitz (find deep shell words freely), Wrapper (given an inner word, find the shells), and Crack (given two boundary letters on each side, find the inner word). Each variation has Classic and Survival sub-modes.', '["A deep shell word is a word where removing the first TWO AND last TWO letters reveals another valid word","Example: STRANGER → RANG, SPLINTER → LINT, SPRINGER → RING","Words must be at least 7 letters long (2 outer + 3 inner + 2 outer)","Blitz: Enter as many deep shell words as you can — Classic gives 90 seconds, Survival resets an 8s clock per word","Wrapper: Given an inner word, find outer shells — Classic finds all in 2 min, Survival gives 8s per wrapper","Crack: Given two boundary letters on each side, type a word that fits in the middle to form a deep shell word","Crack Classic: 10 rounds at your own pace. Crack Survival: 8s per boundary pair","The server validates all words — the dictionary never leaves the server"]', 'hard', '2-3 min', 'Shell', 'hsl(200, 70%, 40%)', 0, true, false);
